(() => {
'use strict';
const cards=window.RFA_TF, $=id=>document.getElementById(id), key='rfa-atlas-true-false-v1';
let marks={},current=null,visible=[],revealed=false;
try { marks=JSON.parse(localStorage.getItem(key)||'{}'); if(!marks||typeof marks!=='object'||Array.isArray(marks))marks={}; }catch{}
const math=el=>renderMathInElement(el,{delimiters:[{left:'$',right:'$',display:false}],throwOnError:false});
function save(){try{localStorage.setItem(key,JSON.stringify(marks));}catch{$('storage').textContent='Browser storage is unavailable. Progress lasts for this visit only.';}}
function filter(){const sheet=$('sheet').value,status=$('status').value,q=$('search').value.toLowerCase().trim();visible=cards.filter(c=>(sheet==='all'||String(c.sheet)===sheet)&&(status==='all'||(marks[c.id]||'new')===status)&&(!q||c.statement.toLowerCase().includes(q)));if(!visible.some(c=>c.id===current))current=visible[0]?.id||null;render();}
function render(){const c=visible.find(c=>c.id===current);revealed=false;$('answer').hidden=true;$('choices').hidden=false;$('reveal').hidden=false;$('card').hidden=!c;$('empty').hidden=!!c;for(const id of ['prev','next','random'])$(id).disabled=visible.length<2;$('position').textContent=c?`${visible.indexOf(c)+1} / ${visible.length}`:'0 cards';$('source').textContent=c?`Sheet ${c.sheet} · True/False ${c.number}`:'';$('progress').textContent=`${cards.filter(c=>marks[c.id]==='known').length} / 49 understood · ${cards.filter(c=>marks[c.id]==='again').length} to review again`;
if(c){$('statement').textContent=c.statement;math($('statement'));$('verdict').textContent='';$('reason').textContent='';}
$('browse').replaceChildren();visible.forEach(c=>{const b=document.createElement('button');b.textContent=`S${c.sheet} · ${c.number}. ${c.statement}`;b.className=c.id===current?'active':'';b.onclick=()=>{current=c.id;render();$('card').focus();};$('browse').append(b);});math($('browse'));}
function reveal(choice){const c=visible.find(c=>c.id===current);if(!c||revealed)return;revealed=true;$('answer').hidden=false;$('choices').hidden=true;$('reveal').hidden=true;$('verdict').textContent=`${c.answer?'True':'False'}${choice===undefined?'':choice===c.answer?' · Correct':' · Revisit your reasoning'}`;$('reason').textContent=c.reason;math($('reason'));}
function move(step){if(!visible.length)return;current=visible[(visible.findIndex(c=>c.id===current)+step+visible.length)%visible.length].id;render();}
for(const id of ['sheet','status'])$(id).onchange=filter;$('search').oninput=filter;$('reveal').onclick=()=>reveal();document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>reveal(b.dataset.answer==='true'));$('prev').onclick=()=>move(-1);$('next').onclick=()=>move(1);$('random').onclick=()=>{const pool=visible.filter(c=>c.id!==current);if(pool.length){current=pool[Math.floor(Math.random()*pool.length)].id;render();}};for(const value of ['again','known'])$(value).onclick=()=>{marks[current]=value;save();const old=current;move(1);if(current===old)current=null;filter();};$('clear').onclick=()=>{$('sheet').value='all';$('status').value='all';$('search').value='';filter();};math(document.querySelector('.intro'));filter();
})();
